module Controller_8_29g (input  x, y, E, F, clock, reset_b);  supply0 GND;  supply1 VCC;  mux_8x1 M3 (m3, GND, GND, F_bar, GND, VCC, GND, VCC, GND, G3, G2, G1);  mux_8x1 M2 (m2, w1, VCC, F, GND, E_bar, GND, VCC, GND, G3, G2, G1);  mux_8x1 M1 (m1, x, GND, F, GND, E, GND, VCC, GND, G3, G2, G1);  DFF_8_29g DM3 (G3, m3, clock, reset_b);  DFF_8_29g DM2 (G2, m2, clock, reset_b);  DFF_8_29g DM1 (G1, m1, clock, reset_b);  decoder_3x8 M0_D (y0, y1, y2, y3, y4, y5, y6, y7, G3, G2, G1);  and (w1, x_bar, y);  not (F_bar, F);  not (E_bar, E);  not (x_bar, x);endmodule// Test plan: Exercise all paths of the ASM chartmodule t_Controller_8_29g ();  reg  x, y, E, F, clock, reset_b;  Controller_8_29g M0 (x, y, E, F, clock, reset_b);  wire [2: 0] state = {M0.G3, M0.G2, M0.G1};  initial #500 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin end  initial fork    reset_b = 0; #2 reset_b = 1;    #0 begin x = 1; y = 1; E = 1; F = 1; end	// Path: S_0, S_1, S_2, S_34    #80 reset_b = 0; #92 reset_b = 1;     #90 begin x = 1; y = 1; E = 1; F = 0; end    #150 reset_b = 0;     #152 reset_b = 1;    #150 begin x = 1; y = 1; E = 0; F = 0; end	// Path: S_0, S_1, S_2, S_4, S_5    #200 reset_b = 0;     #202 reset_b = 1;    #190 begin x = 1; y = 1; E = 0; F = 0; end	// Path: S_0, S_1, S_2, S_4, S_6, S_7    #250 reset_b = 0;     #252 reset_b = 1;    #240 begin x = 0; y = 0; E = 0; F = 0; end	// Path: S_0    #290 reset_b = 0;     #292 reset_b = 1;    #280 begin x = 0; y = 1; E = 0; F = 0; end	// Path: S_0, S_2, S_4, S_6, S_7    #360 reset_b = 0;     #362 reset_b = 1;    #350 begin x = 0; y = 1; E = 1; F = 0; end	// Path: S_0, S_2, S_4, S_5    #420 reset_b = 0;     #422 reset_b = 1;    #410 begin x = 0; y = 1; E = 0; F = 1; end	// Path: S_0, S_2, S_3  joinendmodulemodule  mux_8x1 (output reg y, input x0, x1, x2, x3, x4, x5, x6, x7, s2, s1, s0);  always @ (x0, x1, x2, x3, x4, x5, x6, x7, s0, s1, s2)    case ({s2, s1, s0})      3'b000: y = x0;      3'b001: y = x1;      3'b010: y = x2;            3'b011: y = x3;      3'b100: y = x4;      3'b101: y = x5;      3'b110: y = x6;      3'b111: y = x7;    endcaseendmodulemodule DFF_8_29g (output reg q, input data, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (!reset_b) q <= 1'b0; else q <= data;endmodulemodule  decoder_3x8 (output reg y0, y1, y2, y3, y4, y5, y6, y7, input x2, x1, x0);  always @ (x0, x1, x2) begin    {y7, y6, y5, y4, y3, y2, y1, y0} = 8'b0;    case ({x2, x1, x0})      3'b000: y0= 1'b1;      3'b001: y1= 1'b1;      3'b010: y2= 1'b1;            3'b011: y3= 1'b1;      3'b100: y4= 1'b1;      3'b101: y5= 1'b1;      3'b110: y6= 1'b1;      3'b111: y7= 1'b1;    endcase;  endendmodule